import re

_VERSION = re.compile(r"(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?")


def parse_version(text):
    m = _VERSION.fullmatch(text)
    if not m:
        raise ValueError(f"not a version: {text!r}")
    pre = ()
    if m.group(4):
        parts = []
        for p in m.group(4).split("."):
            if p.isdigit():
                if len(p) > 1 and p[0] == "0":
                    raise ValueError(f"leading zero in {text!r}")
                parts.append(int(p))
            else:
                parts.append(p)
        pre = tuple(parts)
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), pre)


def _cmp(x, y):
    return (x > y) - (x < y)


def _compare_pre(a, b):
    if a == b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        if x == y:
            continue
        if isinstance(x, int) and isinstance(y, int):
            return _cmp(x, y)
        if isinstance(x, int):
            return -1
        if isinstance(y, int):
            return 1
        return _cmp(x, y)
    return _cmp(len(a), len(b))


def compare(a, b):
    va, vb = parse_version(a), parse_version(b)
    core = _cmp(va[:3], vb[:3])
    return core if core else _compare_pre(va[3], vb[3])


def bump(text, part):
    major, minor, patch, pre = parse_version(text)
    if part == "major":
        if pre and minor == 0 and patch == 0:
            return f"{major}.0.0"
        return f"{major + 1}.0.0"
    if part == "minor":
        if pre and patch == 0:
            return f"{major}.{minor}.0"
        return f"{major}.{minor + 1}.0"
    if part == "patch":
        if pre:
            return f"{major}.{minor}.{patch}"
        return f"{major}.{minor}.{patch + 1}"
    raise ValueError(f"unknown part: {part!r}")

