@test("parse")
def _():
    check_eq(parse_version("1.4.0"), (1, 4, 0, ()))
    check_eq(parse_version("1.4.0-rc.2"), (1, 4, 0, ("rc", 2)))
    for bad in ["1.4", "1.4.0.1", "01.0.0", "1.0.0-", "v1.0.0", "1.0.0-rc.01"]:
        check_raises(ValueError, parse_version, bad)

@test("compare release numbers")
def _():
    check_eq(compare("1.10.0", "1.9.9"), 1)
    check_eq(compare("2.0.0", "2.0.0"), 0)
    check_eq(compare("0.9.1", "1.0.0"), -1)

@test("pre-releases come before the release")
def _():
    check_eq(compare("1.0.0-rc.1", "1.0.0"), -1)
    check_eq(compare("1.0.0", "1.0.0-alpha"), 1)

@test("pre-release parts")
def _():
    order = ["1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta", "1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0"]
    for a, b in zip(order, order[1:]):
        check_eq(compare(a, b), -1)
        check_eq(compare(b, a), 1)

@test("bump")
def _():
    check_eq(bump("1.4.2", "patch"), "1.4.3")
    check_eq(bump("1.4.2", "minor"), "1.5.0")
    check_eq(bump("1.4.2", "major"), "2.0.0")
    check_eq(bump("2.0.0-rc.1", "patch"), "2.0.0")
    check_raises(ValueError, bump, "1.0.0", "build")

